using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
namespace CafeLife {
 public static class CafeAspectChecks {
  static readonly BindingFlags instance=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
  static readonly System.Collections.Generic.List<int> temporary=new System.Collections.Generic.List<int>();
  static Type FindType(string name)=>AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType(name)).First(t=>t!=null);
  static EditorWindow view;static PropertyInfo selection;static int original=-1;static object group;
  public static string Report="";
  public static void SetSize(int width,int height){var sizesType=FindType("UnityEditor.GameViewSizes");var singleton=sizesType.GetProperty("instance",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.FlattenHierarchy).GetValue(null);var getGroup=sizesType.GetMethod("GetGroup",instance);group=getGroup.Invoke(singleton,new[]{Enum.Parse(getGroup.GetParameters()[0].ParameterType,"Standalone")});var sizeType=FindType("UnityEditor.GameViewSize");var ctor=sizeType.GetConstructors(instance).First(c=>c.GetParameters().Length==4);var fixedType=Enum.Parse(ctor.GetParameters()[0].ParameterType,"FixedResolution");var size=ctor.Invoke(new object[]{fixedType,width,height,"Cafe layout "+width+"x"+height});group.GetType().GetMethod("AddCustomSize",instance).Invoke(group,new[]{size});int built=(int)group.GetType().GetMethod("GetBuiltinCount",instance).Invoke(group,null),custom=(int)group.GetType().GetMethod("GetCustomCount",instance).Invoke(group,null);view=EditorWindow.GetWindow(FindType("UnityEditor.GameView"));selection=view.GetType().GetProperty("selectedSizeIndex",instance);if(original<0)original=(int)selection.GetValue(view);temporary.Add(built+custom-1);selection.SetValue(view,built+custom-1);view.Repaint();}
  public static void Validate(CafeGame game,string label){Canvas.ForceUpdateCanvases();var canvas=GameObject.Find("Cafe HUD");var frame=canvas.GetComponentsInChildren<RectTransform>().First(t=>t.name=="Studio reference frame");var parent=(RectTransform)frame.parent;var corners=new Vector3[4];foreach(var button in frame.GetComponentsInChildren<Button>()){((RectTransform)button.transform).GetWorldCorners(corners);foreach(var corner in corners){var local=parent.InverseTransformPoint(corner);if(local.x<parent.rect.xMin-1||local.x>parent.rect.xMax+1||local.y<parent.rect.yMin-1||local.y>parent.rect.yMax+1)throw new Exception(label+" menu button outside safe area: "+button.GetComponentInChildren<Text>().text);}}Report+="PASS "+label+" menu buttons fit safe area at "+Screen.width+"x"+Screen.height+"\n";}
  public static void ValidateTouch(CafeGame game){Canvas.ForceUpdateCanvases();if(!game.player.movePad.gameObject.activeInHierarchy||!game.player.lookPad.gameObject.activeInHierarchy||!game.player.sprintPad.gameObject.activeInHierarchy)throw new Exception("Touch preview controls are inactive");var corners=new Vector3[4];var safe=GameObject.Find("Cafe HUD").GetComponentsInChildren<RectTransform>().First(t=>t.name=="Safe area");foreach(var b in safe.GetComponentsInChildren<Button>()){((RectTransform)b.transform).GetWorldCorners(corners);foreach(var c in corners){var p=safe.InverseTransformPoint(c);if(!safe.rect.Contains(p))throw new Exception("Touch button outside safe area: "+b.GetComponentInChildren<Text>().text);}}Report+="PASS Mobile touch HUD buttons fit phone safe area\n";}
  public static void ValidateLatte(){var layout=CafeLattePour.StudioLayout(Screen.safeArea,Screen.height);float scale=layout.width/1120f;var safe=new Rect(Screen.safeArea.x,Screen.height-Screen.safeArea.yMax,Screen.safeArea.width,Screen.safeArea.height);foreach(var b in CafeLattePour.StudioButtons){var rendered=new Rect(layout.position+b.position*scale,b.size*scale);if(!safe.Contains(rendered.min)||!safe.Contains(rendered.max))throw new Exception("Latte action outside safe area");if(b.Overlaps(new Rect(CafeLattePour.PourCenter-Vector2.one*CafeLattePour.PourRadius,Vector2.one*CafeLattePour.PourRadius*2)))throw new Exception("Latte action overlaps pouring surface");}foreach(var p in new[]{Vector2.zero,new Vector2(.7f,-.4f)}){var screen=layout.position+(CafeLattePour.PourCenter+p*CafeLattePour.PourRadius)*scale;var roundtrip=((screen-layout.position)/scale-CafeLattePour.PourCenter)/CafeLattePour.PourRadius;if(Vector2.Distance(p,roundtrip)>.0001f)throw new Exception("Latte input mapping shifted");}Report+="PASS Latte studio actions and pouring coordinates fit "+Screen.width+"x"+Screen.height+"\n";}
  public static void Restore(){if(view&&selection!=null&&original>=0)selection.SetValue(view,original);original=-1;if(group!=null){var remove=group.GetType().GetMethod("RemoveCustomSize",instance);if(remove!=null){var labels=(string[])group.GetType().GetMethod("GetDisplayTexts",instance).Invoke(group,null);for(int i=labels.Length-1;i>=0;i--)if(labels[i].Contains("Cafe layout "))remove.Invoke(group,new object[]{i});}}temporary.Clear();}
 }
}



